pm.test("Verificando se o Body (urlencoded) esta ok", function(){
    pm.expect(pm.request.body).to.exist;
    pm.expect(pm.request.body.mode).to.eql("urlencoded");
    const camposRecebidos = pm.request.body.urlencoded.map(item => item.key);
    const propriedadesEsperadas = propriedades;
    pm.expect(camposRecebidos).to.include.members(propriedadesEsperadas);
    const body = pm.request.body.urlencoded;
    const camposParaValidar = ["name", "status"];
    camposParaValidar.forEach(campo => {
        const item = body.find(element => element.key === campo);
        pm.expect(item, `O campo '${campo}' não foi encontrado no body`).to.not.be.undefined;
        const valor = item.value ? item.value.trim() : "";
        pm.expect(valor, `O campo '${campo}' está vazio`).to.not.be.empty;
    });
});

